"""Rows from Benedek Lang's repertory of early-modern Hungarian ciphertexts (MTA doctoral thesis 2015, pp. 191-330).
Only rows Lang marks undeciphered ('megfejtetlen', 'nincs feltorve', 'feloldatlan', 'nincsen feloldva') are used."""
import sys
sys.stdout.reconfigure(encoding='utf-8')
from cand import add
LANG = {'label': 'Lang 2015, Titkosirás a kora ujkori Magyarországon (MTA doctoral thesis, repertory pp. 191-330)',
        'href': 'https://real-d.mtak.hu/922/7/dc_758_13_doktori_mu.pdf'}


def base(**kw):
    p = kw.pop('p')
    r = dict(region='Central Europe', seen='catalogue', source='Sweep D, Lang 2015 repertory',
             score_note=f"Scored from Lang's repertory entry (thesis p. {p}) during the Nov 2026 sweep D (research/sweep_2026-11_D_east_north/); ciphertext not viewed",
             prior_art=f'open as far as checked (4 Nov 2026: Lang 2015 repertory p. {p} marks it undeciphered; known.py on shelfmark and names, no hit; web search found no decipherment; Tomokiyo, Lasry, DECODE not searched for this item)')
    r.update(kw)
    r['links'] = [dict(LANG, label=LANG['label'] + f', p. {p}')] + r.get('links', [])
    return r


